def fibonacci(n):
    """Return the nth Fibonacci number."""
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

for i in range(10):
    print(fibonacci(i))

pub fn encode<'a, T: AsRef<str> + ?Sized>(&'a self, text: &'a T) -> Result<Vec<u32>> {
    let ids = self.inner.encode(text.as_ref(), false)?;
    Ok(ids.get_ids().to_vec())
}

class Node:
    def __init__(self, value: int) -> None:
        self.value = value
        self.children: list['Node'] = []

    def walk(self):
        yield self
        for child in self.children:
            yield from child.walk()
